nextflow_process {

    name "Test Process GANON_CLASSIFY"
    script "../main.nf"
    process "GANON_CLASSIFY"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "ganon"
    tag "ganon/buildcustom"
    tag "ganon/classify"

    setup {
            run("GANON_BUILDCUSTOM") {
                script "../../buildcustom/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                    input[1] = []
                    input[2] = []
                    input[3] = []
                    """
                }
            }
    }

    test("sarscov2 single-end [fastq]") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true) ]
                ]
                input[1] = GANON_BUILDCUSTOM.out.db.map{it[1]}
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.tre,
                    process.out.report,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match()},
                { assert file(process.out.log[0][1]).text.contains("Total elapsed time:") }
            )
        }

    }

    test("sarscov2 paired-end [fastq]") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = GANON_BUILDCUSTOM.out.db.map{it[1]}
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                        process.out.tre,
                        process.out.report,
                        process.out.findAll { key, val -> key.startsWith('versions') }
                    ).match()
                },
                { assert file(process.out.log[0][1]).text.contains("Total elapsed time:") }
            )
        }

    }

    test("sarscov2 - fastq - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                    ]
                ]
                input[1] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

